  updated_at INTEGER NOT NULL CHECK(updated_at >= created_at)
, enqueue_sequence INTEGER CHECK(enqueue_sequence IS NULL OR enqueue_sequence BETWEEN 1 AND 9007199254740990)) STRICT;
