CREATE TRIGGER account_rate_limit_reset_attempt_identity_guard
BEFORE UPDATE OF profile_id,origin_process_generation,account_fingerprint,
  weekly_window_resets_at,observed_used_percent,created_at
ON account_rate_limit_reset_attempts
WHEN OLD.profile_id!=NEW.profile_id
  OR OLD.origin_process_generation!=NEW.origin_process_generation
  OR OLD.account_fingerprint!=NEW.account_fingerprint
  OR OLD.weekly_window_resets_at!=NEW.weekly_window_resets_at
  OR OLD.observed_used_percent!=NEW.observed_used_percent
  OR OLD.created_at!=NEW.created_at
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset identity is immutable'); END;
CREATE TRIGGER account_rate_limit_reset_attempt_policy_begin_guard
BEFORE UPDATE OF state ON account_rate_limit_reset_attempts
WHEN NEW.state='effect_started'
  AND OLD.state!='effect_started'
  AND NOT EXISTS (
    SELECT 1 FROM account_rate_limit_reset_policies p
    WHERE p.profile_id=OLD.profile_id
      AND p.state='active_bound'
      AND p.account_fingerprint=OLD.account_fingerprint
      AND (
        (
          OLD.state IN ('prepared','retryable')
          AND p.weekly_window_resets_at=OLD.weekly_window_resets_at
        ) OR (
          OLD.state='ambiguous'
          AND p.weekly_window_resets_at>=OLD.weekly_window_resets_at
        )
      )
  )
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset policy does not authorize dispatch'); END;
CREATE TRIGGER account_rate_limit_reset_attempt_policy_close_guard
BEFORE UPDATE OF state ON account_rate_limit_reset_attempts
WHEN NEW.state='closed'
  AND OLD.state!='closed'
  AND NOT EXISTS (
    SELECT 1 FROM account_rate_limit_reset_policies p
    WHERE p.profile_id=OLD.profile_id
      AND (
        (
          p.state='active_bound'
          AND p.account_fingerprint=OLD.account_fingerprint
          AND p.weekly_window_resets_at>=OLD.weekly_window_resets_at
        ) OR (
          NEW.local_resolution='account_identity_changed'
          AND p.state='window_suppressed'
        ) OR (
          NEW.local_resolution='weekly_window_changed'
          AND p.state='window_suppressed'
          AND p.account_fingerprint=OLD.account_fingerprint
          AND p.weekly_window_resets_at>OLD.weekly_window_resets_at
        )
      )
  )
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset policy does not authorize closure'); END;
CREATE TRIGGER account_rate_limit_reset_attempt_policy_insert_guard
BEFORE INSERT ON account_rate_limit_reset_attempts
WHEN NOT EXISTS (
  SELECT 1 FROM account_rate_limit_reset_policies p
  WHERE p.profile_id=NEW.profile_id
    AND p.state='active_bound'
    AND p.account_fingerprint=NEW.account_fingerprint
    AND p.weekly_window_resets_at=NEW.weekly_window_resets_at
)
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset policy does not authorize preparation'); END;
CREATE TRIGGER account_rate_limit_reset_attempt_rebind_guard
BEFORE UPDATE OF current_process_generation ON account_rate_limit_reset_attempts
WHEN OLD.current_process_generation!=NEW.current_process_generation
  AND NOT EXISTS (
    SELECT 1 FROM account_rate_limit_reset_rebinds r
    WHERE r.idempotency_key=OLD.idempotency_key
      AND r.from_process_generation=OLD.current_process_generation
      AND r.to_process_generation=NEW.current_process_generation
      AND r.account_fingerprint=OLD.account_fingerprint
  )
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset rebind evidence is missing'); END;
CREATE TRIGGER account_rate_limit_reset_attempt_terminal_evidence_guard
BEFORE UPDATE OF outcome,local_resolution ON account_rate_limit_reset_attempts
WHEN OLD.state IN ('settled','closed')
  AND (
    OLD.outcome IS NOT NEW.outcome
    OR OLD.local_resolution IS NOT NEW.local_resolution
  )
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset terminal evidence is immutable'); END;
CREATE TRIGGER account_rate_limit_reset_attempt_transition_guard
BEFORE UPDATE OF state ON account_rate_limit_reset_attempts
WHEN NOT (
  (OLD.state='prepared' AND NEW.state='effect_started') OR
  (OLD.state='effect_started' AND NEW.state IN ('ambiguous','retryable','settled')) OR
  (OLD.state IN ('ambiguous','retryable') AND NEW.state='effect_started') OR
  (OLD.state IN ('prepared','retryable') AND NEW.state='closed') OR
  (
    OLD.state='ambiguous'
    AND NEW.state='closed'
    AND NEW.local_resolution='account_identity_changed'
  ) OR
  OLD.state=NEW.state
)
BEGIN SELECT RAISE(ABORT, 'illegal account rate-limit reset transition'); END;
CREATE TRIGGER account_rate_limit_reset_policy_delete_guard
BEFORE DELETE ON account_rate_limit_reset_policies
WHEN EXISTS (
  SELECT 1 FROM profiles p WHERE p.id=OLD.profile_id AND p.state!='removed'
)
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset policy is required'); END;
CREATE TRIGGER account_rate_limit_reset_policy_insert_guard
BEFORE INSERT ON account_rate_limit_reset_policies
WHEN NEW.state NOT IN ('active_unbound','reconciliation_required')
  OR NOT EXISTS (
    SELECT 1 FROM profiles p
    WHERE p.id=NEW.profile_id AND p.state!='removed'
  )
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset policy insert is invalid'); END;
CREATE TRIGGER account_rate_limit_reset_policy_transition_guard
BEFORE UPDATE ON account_rate_limit_reset_policies
WHEN NEW.profile_id!=OLD.profile_id
  OR NEW.created_at!=OLD.created_at
  OR NEW.revision!=OLD.revision+1
  OR NEW.updated_at<OLD.updated_at
  OR NOT (
    (
      OLD.state='active_unbound'
      AND NEW.state='active_bound'
    ) OR (
      OLD.state='reconciliation_required'
      AND NEW.state='window_suppressed'
    ) OR (
      OLD.state='window_suppressed'
      AND NEW.state='active_bound'
      AND NEW.account_fingerprint=OLD.account_fingerprint
      AND NEW.weekly_window_resets_at>OLD.weekly_window_resets_at
      AND NEW.updated_at>=OLD.weekly_window_resets_at
    ) OR (
      OLD.state IN (
        'active_unbound','reconciliation_required','window_suppressed','active_bound'
      )
      AND NEW.state='reconciliation_required'
    ) OR (
      OLD.state='active_bound'
      AND NEW.state='active_bound'
      AND NEW.account_fingerprint=OLD.account_fingerprint
      AND NEW.weekly_window_resets_at>OLD.weekly_window_resets_at
    )
  )
BEGIN SELECT RAISE(ABORT, 'illegal account rate-limit reset policy transition'); END;
CREATE TRIGGER account_rate_limit_reset_rebind_delete_guard
BEFORE DELETE ON account_rate_limit_reset_rebinds
WHEN EXISTS (
  SELECT 1 FROM account_rate_limit_reset_attempts a
  WHERE a.idempotency_key=OLD.idempotency_key
)
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset rebind evidence is append-only'); END;
CREATE TRIGGER account_rate_limit_reset_rebind_insert_guard
BEFORE INSERT ON account_rate_limit_reset_rebinds
WHEN NOT EXISTS (
  SELECT 1 FROM account_rate_limit_reset_attempts a
  WHERE a.idempotency_key=NEW.idempotency_key
    AND a.current_process_generation=NEW.from_process_generation
    AND a.account_fingerprint=NEW.account_fingerprint
    AND a.state IN ('prepared','ambiguous','retryable')
)
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset rebind authority is invalid'); END;
CREATE TRIGGER account_rate_limit_reset_rebind_policy_guard
BEFORE INSERT ON account_rate_limit_reset_rebinds
WHEN NOT EXISTS (
  SELECT 1
  FROM account_rate_limit_reset_attempts a
  JOIN account_rate_limit_reset_policies p ON p.profile_id=a.profile_id
  WHERE a.idempotency_key=NEW.idempotency_key
    AND p.state='active_bound'
    AND p.account_fingerprint=a.account_fingerprint
    AND (
      (
        a.state IN ('prepared','retryable')
        AND p.weekly_window_resets_at=a.weekly_window_resets_at
      ) OR (
        a.state='ambiguous'
        AND p.weekly_window_resets_at>=a.weekly_window_resets_at
      )
    )
)
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset policy does not authorize rebind'); END;
CREATE TRIGGER account_rate_limit_reset_rebind_update_guard
BEFORE UPDATE ON account_rate_limit_reset_rebinds
BEGIN SELECT RAISE(ABORT, 'account rate-limit reset rebind evidence is append-only'); END;
CREATE TRIGGER desktop_switch_resolutions_immutable_delete
BEFORE DELETE ON desktop_switch_resolutions
BEGIN SELECT RAISE(ABORT, 'desktop switch resolution is immutable'); END;
CREATE TRIGGER desktop_switch_resolutions_immutable_update
BEFORE UPDATE ON desktop_switch_resolutions
BEGIN SELECT RAISE(ABORT, 'desktop switch resolution is immutable'); END;
CREATE TRIGGER desktop_switch_transition_guard BEFORE UPDATE OF phase ON desktop_switches
WHEN NOT (
  (OLD.phase = 'prepared' AND NEW.phase IN ('prepared','quit_started','launch_started','failed','ambiguous')) OR
  (OLD.phase = 'quit_started' AND NEW.phase IN ('quit_started','quit_confirmed','ambiguous')) OR
  (OLD.phase = 'quit_confirmed' AND NEW.phase IN ('quit_confirmed','launch_started','ambiguous')) OR
  (OLD.phase = 'launch_started' AND NEW.phase IN ('launch_started','verify_started','ambiguous')) OR
  (OLD.phase = 'verify_started' AND NEW.phase IN ('verify_started','applied','ambiguous')) OR
  OLD.phase = NEW.phase
)
BEGIN SELECT RAISE(ABORT, 'illegal desktop switch transition'); END;
CREATE TRIGGER mutation_effect_evidence_immutable_delete
BEFORE DELETE ON mutation_effect_evidence
BEGIN SELECT RAISE(ABORT, 'mutation effect evidence is immutable'); END;
CREATE TRIGGER mutation_effect_evidence_immutable_update
BEFORE UPDATE ON mutation_effect_evidence
BEGIN SELECT RAISE(ABORT, 'mutation effect evidence is immutable'); END;
CREATE TRIGGER mutation_resolutions_immutable_delete
BEFORE DELETE ON mutation_resolutions
BEGIN SELECT RAISE(ABORT, 'mutation resolution is immutable'); END;
CREATE TRIGGER mutation_resolutions_immutable_update
BEFORE UPDATE ON mutation_resolutions
BEGIN SELECT RAISE(ABORT, 'mutation resolution is immutable'); END;
CREATE TRIGGER mutation_transition_guard BEFORE UPDATE OF state ON mutation_attempts
WHEN NOT (
  (OLD.state = 'prepared' AND NEW.state IN ('effect_started','cancelled')) OR
  (OLD.state = 'effect_started' AND NEW.state IN ('applied','failed','ambiguous')) OR
  OLD.state = NEW.state
)
BEGIN SELECT RAISE(ABORT, 'illegal mutation transition'); END;
CREATE TRIGGER profiles_label_key_immutable
BEFORE UPDATE OF label,label_key ON profiles
WHEN NEW.label IS NOT OLD.label OR NEW.label_key IS NOT OLD.label_key
BEGIN SELECT RAISE(ABORT, 'profile label identity is immutable'); END;
CREATE TRIGGER profiles_label_key_insert_guard
BEFORE INSERT ON profiles
WHEN NEW.label_key IS NULL
  OR length(CAST(NEW.label_key AS BLOB)) NOT BETWEEN 1 AND 4096
BEGIN SELECT RAISE(ABORT, 'invalid profile label key'); END;
CREATE TRIGGER projects_label_key_immutable
BEFORE UPDATE OF label,label_key ON projects
WHEN NEW.label IS NOT OLD.label OR NEW.label_key IS NOT OLD.label_key
BEGIN SELECT RAISE(ABORT, 'project label identity is immutable'); END;
CREATE TRIGGER projects_label_key_insert_guard
BEFORE INSERT ON projects
WHEN NEW.label_key IS NULL
  OR length(CAST(NEW.label_key AS BLOB)) NOT BETWEEN 1 AND 4096
BEGIN SELECT RAISE(ABORT, 'invalid project label key'); END;
CREATE TRIGGER provider_interaction_transitions_immutable_delete
BEFORE DELETE ON provider_interaction_transitions
BEGIN SELECT RAISE(ABORT, 'provider interaction transition is immutable'); END;
CREATE TRIGGER provider_interaction_transitions_immutable_update
BEFORE UPDATE ON provider_interaction_transitions
BEGIN SELECT RAISE(ABORT, 'provider interaction transition is immutable'); END;
CREATE TRIGGER provider_interactions_authority_guard
BEFORE INSERT ON provider_interactions
WHEN NOT EXISTS(
  SELECT 1 FROM profiles p
  WHERE p.id=NEW.profile_id
    AND p.process_generation=NEW.process_generation
    AND p.state!='removed'
    AND (
      NEW.session_id IS NULL
      OR EXISTS(
        SELECT 1 FROM sessions s
        WHERE s.id=NEW.session_id AND s.profile_id=NEW.profile_id
      )
    )
)
BEGIN SELECT RAISE(ABORT, 'provider interaction authority mismatch'); END;
CREATE TRIGGER provider_interactions_authority_immutable
BEFORE UPDATE OF session_id,profile_id,process_generation,connection_id,
  request_id_type,request_id_number,request_id_text,method,request_digest,
  thread_id,turn_id,item_id,approval_id,kind,blocking,display_json,requested_at,deadline_at
ON provider_interactions
BEGIN SELECT RAISE(ABORT, 'provider interaction authority is immutable'); END;
CREATE TRIGGER provider_interactions_current_generation_prepare
BEFORE UPDATE OF state ON provider_interactions
WHEN NEW.state='response_prepared' AND NOT EXISTS(
  SELECT 1 FROM profiles p
  WHERE p.id=OLD.profile_id
    AND p.process_generation=OLD.process_generation
    AND p.state!='removed'
)
BEGIN SELECT RAISE(ABORT, 'provider interaction generation is stale'); END;
CREATE TRIGGER provider_interactions_intent_immutable
BEFORE UPDATE OF intended_terminal_state ON provider_interactions
WHEN NOT (
  (
    OLD.state='pending'
    AND NEW.state='response_prepared'
    AND OLD.intended_terminal_state IS NULL
    AND NEW.intended_terminal_state IS NOT NULL
    AND OLD.response_digest IS NULL
    AND NEW.response_digest IS NOT NULL
    AND OLD.response_expected_revision IS NULL
    AND NEW.response_expected_revision=OLD.revision
    AND NEW.revision=OLD.revision+1
  )
  OR
  (
    OLD.state='response_prepared'
    AND NEW.state='response_prepared'
    AND OLD.intended_terminal_state IN ('resolved','declined','canceled')
    AND NEW.intended_terminal_state='expired'
    AND OLD.response_digest IS NOT NULL
    AND NEW.response_digest IS NOT NULL
    AND NEW.response_digest!=OLD.response_digest
    AND NEW.response_expected_revision=OLD.response_expected_revision
    AND NEW.revision=OLD.revision+1
    AND NEW.terminal_at IS NULL
    AND NEW.updated_at>=OLD.deadline_at
  )
)
BEGIN SELECT RAISE(ABORT, 'provider interaction terminal intent is immutable'); END;
CREATE TRIGGER provider_interactions_intent_insert_guard
BEFORE INSERT ON provider_interactions
WHEN NEW.intended_terminal_state IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'pending provider interaction cannot have terminal intent'); END;
CREATE TRIGGER provider_interactions_intent_state_guard
BEFORE UPDATE OF state,intended_terminal_state ON provider_interactions
WHEN
  (NEW.state IN ('response_prepared','response_written') AND NEW.intended_terminal_state IS NULL)
  OR (
    OLD.state='response_written'
    AND NEW.state IN ('resolved','declined','canceled','expired')
    AND NEW.state IS NOT OLD.intended_terminal_state
  )
BEGIN SELECT RAISE(ABORT, 'provider interaction terminal state contradicts prepared intent'); END;
CREATE TRIGGER provider_interactions_mcp_url_guard_insert
BEFORE INSERT ON provider_interactions
WHEN NEW.kind='mcp_elicitation' AND (
  json_extract(NEW.display_json,'$.mode')='url'
  OR COALESCE(json_type(NEW.display_json,'$.url'),'null')!='null'
)
BEGIN SELECT RAISE(ABORT, 'MCP URL interaction cannot enter durable state'); END;
CREATE TRIGGER provider_interactions_mcp_url_guard_update
BEFORE UPDATE OF kind,display_json ON provider_interactions
WHEN NEW.kind='mcp_elicitation' AND (
  json_extract(NEW.display_json,'$.mode')='url'
  OR COALESCE(json_type(NEW.display_json,'$.url'),'null')!='null'
)
BEGIN SELECT RAISE(ABORT, 'MCP URL interaction cannot enter durable state'); END;
CREATE TRIGGER provider_interactions_permission_value_guard_insert
BEFORE INSERT ON provider_interactions
WHEN NEW.kind='permission_approval' AND EXISTS(
  SELECT 1 FROM json_each(json_extract(NEW.display_json,'$.requested'))
  WHERE json_type(value,'$.value') IS NOT NULL
)
BEGIN SELECT RAISE(ABORT, 'permission values cannot enter durable interaction display state'); END;
CREATE TRIGGER provider_interactions_permission_value_guard_update
BEFORE UPDATE OF kind,display_json ON provider_interactions
WHEN NEW.kind='permission_approval' AND EXISTS(
  SELECT 1 FROM json_each(json_extract(NEW.display_json,'$.requested'))
  WHERE json_type(value,'$.value') IS NOT NULL
)
BEGIN SELECT RAISE(ABORT, 'permission values cannot enter durable interaction display state'); END;
CREATE TRIGGER provider_interactions_response_fields_guard
BEFORE UPDATE OF response_digest,response_expected_revision ON provider_interactions
WHEN NOT (
  (
    OLD.state='pending'
    AND NEW.state='response_prepared'
    AND OLD.response_digest IS NULL
    AND NEW.response_digest IS NOT NULL
    AND OLD.response_expected_revision IS NULL
    AND NEW.response_expected_revision=OLD.revision
    AND OLD.intended_terminal_state IS NULL
    AND NEW.intended_terminal_state IS NOT NULL
    AND NEW.revision=OLD.revision+1
  )
  OR
  (
    OLD.state='response_prepared'
    AND NEW.state='response_prepared'
    AND OLD.intended_terminal_state IN ('resolved','declined','canceled')
    AND NEW.intended_terminal_state='expired'
    AND OLD.response_digest IS NOT NULL
    AND NEW.response_digest IS NOT NULL
    AND NEW.response_digest!=OLD.response_digest
    AND NEW.response_expected_revision=OLD.response_expected_revision
    AND NEW.revision=OLD.revision+1
    AND NEW.terminal_at IS NULL
    AND NEW.updated_at>=OLD.deadline_at
  )
)
BEGIN SELECT RAISE(ABORT, 'provider interaction response authority is immutable'); END;
CREATE TRIGGER provider_interactions_revision_guard
BEFORE UPDATE OF revision ON provider_interactions
WHEN NOT (
  NEW.revision=OLD.revision+1
  AND (
    NEW.state IS NOT OLD.state
    OR (
      OLD.state='response_prepared'
      AND NEW.state='response_prepared'
      AND OLD.intended_terminal_state IN ('resolved','declined','canceled')
      AND NEW.intended_terminal_state='expired'
      AND OLD.response_digest IS NOT NULL
      AND NEW.response_digest IS NOT NULL
      AND NEW.response_digest!=OLD.response_digest
      AND NEW.response_expected_revision=OLD.response_expected_revision
      AND NEW.terminal_at IS NULL
      AND NEW.updated_at>=OLD.deadline_at
    )
  )
)
BEGIN SELECT RAISE(ABORT, 'illegal provider interaction revision transition'); END;
CREATE TRIGGER provider_interactions_transition_guard
BEFORE UPDATE OF state ON provider_interactions
WHEN NOT (
  NEW.revision=OLD.revision+1
  AND (
    (OLD.state='pending' AND NEW.state IN ('response_prepared','resolved','declined','canceled','expired','resolution_unknown'))
    OR (OLD.state='response_prepared' AND NEW.state IN ('response_written','resolved','declined','canceled','expired','resolution_unknown'))
    OR (OLD.state='response_written' AND NEW.state IN ('resolved','declined','canceled','expired','resolution_unknown'))
  )
)
BEGIN SELECT RAISE(ABORT, 'illegal provider interaction transition'); END;
CREATE TRIGGER provider_login_authority_generation_guard
BEFORE UPDATE OF process_generation ON provider_login_authorities
WHEN OLD.state!='active' OR NEW.state!='active' OR NEW.process_generation!=OLD.process_generation+1
BEGIN SELECT RAISE(ABORT, 'illegal provider login generation transition'); END;
CREATE TRIGGER provider_login_authority_identity_immutable
BEFORE UPDATE OF attempt_id,profile_id,login_id,recorded_at ON provider_login_authorities
BEGIN SELECT RAISE(ABORT, 'provider login identity is immutable'); END;
CREATE TRIGGER provider_login_authority_immutable_delete
BEFORE DELETE ON provider_login_authorities
BEGIN SELECT RAISE(ABORT, 'provider login authority is append-only'); END;
CREATE TRIGGER provider_login_authority_state_guard
BEFORE UPDATE OF state,settlement ON provider_login_authorities
WHEN NOT (
  OLD.state='active' AND NEW.state='settled' AND OLD.settlement IS NULL AND NEW.settlement IS NOT NULL
)
BEGIN SELECT RAISE(ABORT, 'illegal provider login settlement transition'); END;
CREATE TRIGGER queue_effect_evidence_immutable_delete
BEFORE DELETE ON queue_effect_evidence
BEGIN SELECT RAISE(ABORT, 'queue effect evidence is immutable'); END;
CREATE TRIGGER queue_effect_evidence_immutable_update
BEFORE UPDATE ON queue_effect_evidence
BEGIN SELECT RAISE(ABORT, 'queue effect evidence is immutable'); END;
CREATE TRIGGER queue_effect_resolution_authority_guard
BEFORE INSERT ON queue_effect_resolutions
WHEN NOT EXISTS(
  SELECT 1
  FROM queue_entries q
  JOIN queue_effect_evidence e ON e.queue_id=q.id
  JOIN sessions s ON s.id=q.session_id
  WHERE q.id=NEW.queue_id
    AND q.state='ambiguous'
    AND s.state!='recovery_required'
)
OR json_valid(NEW.evidence_json)!=1
OR (
  NEW.resolution_kind='proven_applied'
  AND (
    NEW.receipt_json IS NULL
    OR json_valid(NEW.receipt_json)!=1
    OR json_type(NEW.receipt_json)!='object'
    OR json_type(NEW.receipt_json,'$.turnId')!='text'
    OR length(json_extract(NEW.receipt_json,'$.turnId')) NOT BETWEEN 1 AND 200
    OR NOT EXISTS(
      SELECT 1
      FROM queue_entries q
      JOIN session_turn_runtime_profiles t
        ON t.session_id=q.session_id
       AND t.source_kind='queue_start'
       AND t.source_id=q.id
       AND t.turn_id=json_extract(NEW.receipt_json,'$.turnId')
      WHERE q.id=NEW.queue_id
    )
  )
)
OR (NEW.resolution_kind='abandoned' AND NEW.receipt_json IS NOT NULL)
BEGIN SELECT RAISE(ABORT, 'queue effect resolution authority mismatch'); END;
CREATE TRIGGER queue_effect_resolutions_immutable_delete
BEFORE DELETE ON queue_effect_resolutions
BEGIN SELECT RAISE(ABORT, 'queue effect resolution is immutable'); END;
CREATE TRIGGER queue_effect_resolutions_immutable_update
BEFORE UPDATE ON queue_effect_resolutions
BEGIN SELECT RAISE(ABORT, 'queue effect resolution is immutable'); END;
CREATE TRIGGER queue_enqueue_identity_insert_once
BEFORE INSERT ON queue_entries
WHEN EXISTS(
  SELECT 1 FROM queue_entries
  WHERE id=NEW.id OR enqueue_sequence=NEW.enqueue_sequence
)
BEGIN SELECT RAISE(ABORT, 'queue enqueue identity already exists'); END;
CREATE TRIGGER queue_enqueue_sequence_immutable
BEFORE UPDATE OF enqueue_sequence ON queue_entries
WHEN NEW.enqueue_sequence IS NOT OLD.enqueue_sequence
BEGIN SELECT RAISE(ABORT, 'queue enqueue sequence is immutable'); END;
CREATE TRIGGER queue_enqueue_sequence_required
BEFORE INSERT ON queue_entries
WHEN NEW.enqueue_sequence IS NULL
BEGIN SELECT RAISE(ABORT, 'queue enqueue sequence required'); END;
CREATE TRIGGER queue_message_resolution_scrub
AFTER INSERT ON queue_effect_resolutions
BEGIN
  INSERT INTO queue_message_scrub_authority(singleton,required_at,requires_vacuum,generation)
  VALUES (1,NEW.created_at,0,1)
  ON CONFLICT(singleton) DO UPDATE SET
    required_at=MIN(required_at,excluded.required_at),
    requires_vacuum=MAX(requires_vacuum,excluded.requires_vacuum),
    generation=CASE
      WHEN generation<9007199254740991 THEN generation+1
      ELSE RAISE(ABORT, 'queue message scrub generation exhausted')
    END;
END;
CREATE TRIGGER queue_message_settlement_guard
BEFORE UPDATE OF message ON queue_entries
WHEN NOT (
  NEW.message='[queue message removed after settlement]'
  AND (
    NEW.state IN ('applied','failed','cancelled')
    OR EXISTS(
      SELECT 1 FROM queue_effect_resolutions r WHERE r.queue_id=OLD.id
    )
  )
  AND EXISTS(
    SELECT 1 FROM queue_message_scrub_authority a WHERE a.singleton=1
  )
)
BEGIN SELECT RAISE(ABORT, 'queue message is immutable except for settlement removal'); END;
CREATE TRIGGER queue_message_terminal_insert_scrub
AFTER INSERT ON queue_entries
WHEN NEW.state IN ('applied','failed','cancelled')
BEGIN
  INSERT INTO queue_message_scrub_authority(singleton,required_at,requires_vacuum,generation)
  VALUES (1,NEW.updated_at,0,1)
  ON CONFLICT(singleton) DO UPDATE SET
    required_at=MIN(required_at,excluded.required_at),
    requires_vacuum=MAX(requires_vacuum,excluded.requires_vacuum),
    generation=CASE
      WHEN generation<9007199254740991 THEN generation+1
      ELSE RAISE(ABORT, 'queue message scrub generation exhausted')
    END;
END;
CREATE TRIGGER queue_message_terminal_transition_scrub
AFTER UPDATE OF state ON queue_entries
WHEN NEW.state IN ('applied','failed','cancelled')
BEGIN
  INSERT INTO queue_message_scrub_authority(singleton,required_at,requires_vacuum,generation)
  VALUES (1,NEW.updated_at,0,1)
  ON CONFLICT(singleton) DO UPDATE SET
    required_at=MIN(required_at,excluded.required_at),
    requires_vacuum=MAX(requires_vacuum,excluded.requires_vacuum),
    generation=CASE
      WHEN generation<9007199254740991 THEN generation+1
      ELSE RAISE(ABORT, 'queue message scrub generation exhausted')
    END;
END;
CREATE TRIGGER queue_sequence_authority_insert_once
BEFORE INSERT ON queue_sequence_authority
WHEN EXISTS(SELECT 1 FROM queue_sequence_authority WHERE singleton=1)
BEGIN SELECT RAISE(ABORT, 'queue sequence authority already exists'); END;
CREATE TRIGGER queue_sequence_authority_monotonic
BEFORE UPDATE OF next_sequence ON queue_sequence_authority
WHEN NEW.next_sequence<OLD.next_sequence
BEGIN SELECT RAISE(ABORT, 'queue sequence authority cannot regress'); END;
CREATE TRIGGER queue_sequence_authority_no_delete
BEFORE DELETE ON queue_sequence_authority
BEGIN SELECT RAISE(ABORT, 'queue sequence authority cannot be deleted'); END;
CREATE TRIGGER queue_sequence_authority_singleton_immutable
BEFORE UPDATE OF singleton ON queue_sequence_authority
WHEN NEW.singleton IS NOT OLD.singleton
BEGIN SELECT RAISE(ABORT, 'queue sequence authority singleton is immutable'); END;
CREATE TRIGGER queue_transition_guard BEFORE UPDATE OF state ON queue_entries
WHEN NOT (
  (OLD.state = 'pending' AND NEW.state IN ('dispatching','cancelled')) OR
  (OLD.state = 'dispatching' AND NEW.state IN ('applied','failed','ambiguous'))
)
BEGIN SELECT RAISE(ABORT, 'illegal queue transition'); END;
CREATE TRIGGER session_events_account_authority_guard
BEFORE INSERT ON session_events
WHEN NOT EXISTS(
  SELECT 1 FROM sessions s JOIN profiles p ON p.id=s.profile_id
  WHERE s.id=NEW.session_id
    AND s.profile_id=NEW.account_id
    AND p.process_generation=NEW.provider_generation
)
BEGIN SELECT RAISE(ABORT, 'session event account authority mismatch'); END;
CREATE TRIGGER session_events_accounting_delete
AFTER DELETE ON session_events
BEGIN
  UPDATE session_event_streams
  SET retained_count=retained_count-1,
      retained_bytes=retained_bytes-OLD.event_bytes
  WHERE session_id=OLD.session_id AND stream_epoch=OLD.stream_epoch;
END;
CREATE TRIGGER session_events_accounting_insert
AFTER INSERT ON session_events
BEGIN
  UPDATE session_event_streams
  SET retained_count=retained_count+1,
      retained_bytes=retained_bytes+NEW.event_bytes
  WHERE session_id=NEW.session_id AND stream_epoch=NEW.stream_epoch;
END;
CREATE TRIGGER session_events_immutable_update
BEFORE UPDATE ON session_events
BEGIN SELECT RAISE(ABORT, 'session event is immutable'); END;
CREATE TRIGGER session_runtime_profile_authority_guard
BEFORE INSERT ON session_runtime_profiles
WHEN NOT EXISTS(
  SELECT 1 FROM sessions s
  WHERE s.id=NEW.session_id AND s.profile_id=NEW.profile_id
)
BEGIN SELECT RAISE(ABORT, 'runtime profile session authority mismatch'); END;
CREATE TRIGGER session_runtime_profiles_immutable_delete
BEFORE DELETE ON session_runtime_profiles
BEGIN SELECT RAISE(ABORT, 'session runtime profile is immutable'); END;
CREATE TRIGGER session_runtime_profiles_immutable_update
BEFORE UPDATE ON session_runtime_profiles
BEGIN SELECT RAISE(ABORT, 'session runtime profile is immutable'); END;
CREATE TRIGGER session_start_attempts_immutable_delete
BEFORE DELETE ON session_start_attempts
BEGIN SELECT RAISE(ABORT, 'session start binding is immutable'); END;
CREATE TRIGGER session_start_attempts_immutable_update
BEFORE UPDATE ON session_start_attempts
BEGIN SELECT RAISE(ABORT, 'session start binding is immutable'); END;
CREATE TRIGGER session_task_occurrences_insert_guard
BEFORE INSERT ON session_task_occurrences
WHEN NOT EXISTS(
  SELECT 1 FROM session_tasks t
  WHERE t.id=NEW.task_id
    AND t.session_id=NEW.session_id
    AND t.revision=NEW.task_revision
    AND t.status='active'
    AND t.deleted_at IS NULL
    AND t.next_due_at=NEW.scheduled_for
) OR NOT EXISTS(
  SELECT 1 FROM queue_entries q
  WHERE q.id=NEW.queue_id
    AND q.session_id=NEW.session_id
    AND q.state='pending'
) OR EXISTS(
  SELECT 1
  FROM session_task_occurrences o
  JOIN queue_entries q ON q.id=o.queue_id
  WHERE o.task_id=NEW.task_id
    AND q.state IN ('pending','dispatching','ambiguous')
)
BEGIN SELECT RAISE(ABORT,'SESSION_TASK_OCCURRENCE_AUTHORITY_INVALID'); END;
CREATE TRIGGER session_task_occurrences_no_update
BEFORE UPDATE ON session_task_occurrences
BEGIN SELECT RAISE(ABORT,'SESSION_TASK_OCCURRENCE_IMMUTABLE'); END;
CREATE TRIGGER session_task_receipts_capacity_guard
BEFORE INSERT ON session_task_receipts
WHEN (
  SELECT COUNT(*) FROM session_task_receipts WHERE session_id=NEW.session_id
) >= CASE WHEN NEW.operation='delete' THEN 4096 ELSE 4064 END
BEGIN SELECT RAISE(ABORT,'SESSION_TASK_RECEIPT_CAPACITY'); END;
CREATE TRIGGER session_task_receipts_no_update
BEFORE UPDATE ON session_task_receipts
BEGIN SELECT RAISE(ABORT,'SESSION_TASK_RECEIPT_IMMUTABLE'); END;
CREATE TRIGGER session_tasks_due_advance_guard
BEFORE UPDATE OF next_due_at ON session_tasks
WHEN NEW.revision=OLD.revision AND NOT EXISTS(
  SELECT 1 FROM session_task_occurrences o
  WHERE o.task_id=OLD.id
    AND o.session_id=OLD.session_id
    AND o.task_revision=OLD.revision
    AND o.scheduled_for=OLD.next_due_at
)
BEGIN SELECT RAISE(ABORT,'SESSION_TASK_DUE_ADVANCE_WITHOUT_OCCURRENCE'); END;
CREATE TRIGGER session_tasks_limit_guard
BEFORE INSERT ON session_tasks
WHEN (SELECT COUNT(*) FROM session_tasks WHERE session_id=NEW.session_id AND deleted_at IS NULL) >= 32
BEGIN SELECT RAISE(ABORT,'SESSION_TASK_LIMIT'); END;
CREATE TRIGGER session_tasks_update_guard
BEFORE UPDATE ON session_tasks
WHEN NEW.id != OLD.id
  OR NEW.session_id != OLD.session_id
  OR NEW.schedule_kind != OLD.schedule_kind
  OR NEW.created_at != OLD.created_at
  OR NOT (
    (
      OLD.deleted_at IS NULL
      AND NEW.revision=OLD.revision+1
      AND NEW.updated_at>OLD.updated_at
    ) OR (
      OLD.deleted_at IS NULL
      AND NEW.deleted_at IS NULL
      AND OLD.status='active'
      AND NEW.status='active'
      AND NEW.revision=OLD.revision
      AND NEW.name=OLD.name
      AND NEW.prompt=OLD.prompt
      AND NEW.interval_minutes=OLD.interval_minutes
      AND NEW.updated_at=OLD.updated_at
      AND OLD.next_due_at IS NOT NULL
      AND NEW.next_due_at>OLD.next_due_at
    )
  )
BEGIN SELECT RAISE(ABORT,'SESSION_TASK_UPDATE_INVALID'); END;
CREATE TRIGGER session_turn_runtime_profile_authority_guard
BEFORE INSERT ON session_turn_runtime_profiles
WHEN NOT EXISTS(
  SELECT 1 FROM session_runtime_profiles p
  WHERE p.session_id=NEW.session_id
    AND p.source_kind=NEW.source_kind
    AND p.source_id=NEW.source_id
    AND p.profile_id=NEW.profile_id
    AND p.process_generation=NEW.process_generation
    AND p.observed_at=NEW.observed_at
    AND p.profile_json=NEW.profile_json
)
BEGIN SELECT RAISE(ABORT, 'turn runtime profile source authority mismatch'); END;
CREATE TRIGGER session_turn_runtime_profiles_immutable_delete
BEFORE DELETE ON session_turn_runtime_profiles
BEGIN SELECT RAISE(ABORT, 'turn runtime profile is immutable'); END;
CREATE TRIGGER session_turn_runtime_profiles_immutable_update
BEFORE UPDATE ON session_turn_runtime_profiles
BEGIN SELECT RAISE(ABORT, 'turn runtime profile is immutable'); END;
CREATE TRIGGER work_active_limit_guard
BEFORE INSERT ON works
WHEN NEW.state IN ('active','cancel_pending','fail_pending') AND (
  SELECT COUNT(*) FROM works WHERE state IN ('active','cancel_pending','fail_pending')
) >= 1024
BEGIN SELECT RAISE(ABORT,'WORK_ACTIVE_LIMIT'); END;
CREATE TRIGGER work_attempt_authority_immutable
BEFORE UPDATE OF id,work_id,task_id,worker_session_id,account_id,project_id,preset,fast,fence,account_generation,daemon_generation,created_at ON work_attempts
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_AUTHORITY_IMMUTABLE'); END;
CREATE TRIGGER work_attempt_dispatch_binding_guard
BEFORE UPDATE OF target_session_id,dispatch_mode ON work_attempts
WHEN (OLD.target_session_id IS NOT NULL OR OLD.dispatch_mode IS NOT NULL)
  AND (NEW.target_session_id IS NOT OLD.target_session_id OR NEW.dispatch_mode IS NOT OLD.dispatch_mode)
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_DISPATCH_BINDING_IMMUTABLE'); END;
CREATE TRIGGER work_attempt_fence_monotonic
BEFORE INSERT ON work_attempts
WHEN NEW.fence <= COALESCE((SELECT MAX(fence) FROM work_attempts WHERE task_id=NEW.task_id),0)
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_FENCE_NOT_MONOTONIC'); END;
CREATE TRIGGER work_attempt_no_delete
BEFORE DELETE ON work_attempts
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_IMMUTABLE'); END;
CREATE TRIGGER work_attempt_reports_no_delete
BEFORE DELETE ON work_attempt_reports
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_REPORT_IMMUTABLE'); END;
CREATE TRIGGER work_attempt_reports_no_update
BEFORE UPDATE ON work_attempt_reports BEGIN SELECT RAISE(ABORT,'WORK_REPORT_IMMUTABLE'); END;
CREATE TRIGGER work_attempt_revision_guard
BEFORE UPDATE ON work_attempts
WHEN NEW.revision != OLD.revision + 1
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_REVISION'); END;
CREATE TRIGGER work_attempt_route_guard
BEFORE INSERT ON work_attempts
WHEN NOT EXISTS (
  SELECT 1
  FROM work_tasks AS t
  JOIN sessions AS s ON s.id=NEW.worker_session_id
  JOIN work_members AS m ON m.work_id=NEW.work_id AND m.session_id=s.id
  WHERE t.id=NEW.task_id AND t.work_id=NEW.work_id
    AND t.account_id=NEW.account_id AND t.project_id=NEW.project_id
    AND t.preset=NEW.preset AND t.fast=NEW.fast
    AND s.profile_id=NEW.account_id AND s.project_id=NEW.project_id
    AND s.preset=NEW.preset AND s.fast_enabled=NEW.fast
)
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_ROUTE_MISMATCH'); END;
CREATE TRIGGER work_attempt_state_guard
BEFORE UPDATE OF state ON work_attempts
WHEN NOT (
  OLD.state = NEW.state OR
  (OLD.state = 'claimed' AND NEW.state IN ('dispatching','failed','released','expired','cancelled')) OR
  (OLD.state = 'dispatching' AND NEW.state IN ('running','failed','recovery_required','cancelled')) OR
  (OLD.state = 'running' AND NEW.state IN ('submitted','blocked','failed','recovery_required','cancelled')) OR
  (OLD.state = 'submitted' AND NEW.state IN ('completed','failed','cancelled')) OR
  (OLD.state = 'recovery_required' AND NEW.state IN ('running','submitted','completed','failed','released','cancelled'))
)
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_STATE_TRANSITION'); END;
CREATE TRIGGER work_attempt_submission_guard
BEFORE UPDATE OF submission_id ON work_attempts
WHEN OLD.submission_id IS NOT NULL AND NEW.submission_id IS NOT OLD.submission_id
BEGIN SELECT RAISE(ABORT,'WORK_ATTEMPT_SUBMISSION_IMMUTABLE'); END;
CREATE TRIGGER work_dependencies_no_delete
BEFORE DELETE ON work_task_dependencies
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_DEPENDENCY_IMMUTABLE'); END;
CREATE TRIGGER work_dependencies_no_update
BEFORE UPDATE ON work_task_dependencies BEGIN SELECT RAISE(ABORT,'WORK_DEPENDENCY_IMMUTABLE'); END;
CREATE TRIGGER work_effect_capacity_guard
BEFORE INSERT ON work_prepared_effects
WHEN NEW.state='prepared'
 AND (SELECT COUNT(*) FROM work_events WHERE work_id=NEW.work_id)
   + (SELECT COALESCE(SUM(CASE state WHEN 'prepared' THEN 2 WHEN 'effect_started' THEN 1 ELSE 0 END),0)
      FROM work_prepared_effects WHERE work_id=NEW.work_id)
   + 3 > 65536
BEGIN SELECT RAISE(ABORT,'WORK_HISTORY_EVENT_LIMIT'); END;
CREATE TRIGGER work_effect_identity_immutable
BEFORE UPDATE OF idempotency_key,work_id,effect_kind,subject_id,instruction_json,instruction_digest,daemon_generation,prepared_at ON work_prepared_effects
BEGIN SELECT RAISE(ABORT,'WORK_EFFECT_IDENTITY_IMMUTABLE'); END;
CREATE TRIGGER work_effect_no_delete
BEFORE DELETE ON work_prepared_effects
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_EFFECT_IMMUTABLE'); END;
CREATE TRIGGER work_effect_outcome_guard
BEFORE UPDATE OF outcome_digest,outcome_json,finalized_at ON work_prepared_effects
WHEN OLD.state NOT IN ('prepared','effect_started')
  AND NOT (OLD.state='unknown' AND NEW.state IN ('accepted','failed') AND EXISTS (
    SELECT 1 FROM work_effect_resolutions AS r
    WHERE r.effect_idempotency_key=OLD.idempotency_key
  ))
  AND NOT (OLD.state='unknown' AND NEW.state IN ('accepted','failed') AND EXISTS (
    SELECT 1 FROM work_nested_effect_settlements AS n
    WHERE n.effect_idempotency_key=OLD.idempotency_key AND n.outcome=NEW.state
  ))
  AND (
  NEW.outcome_digest IS NOT OLD.outcome_digest OR
  NEW.outcome_json IS NOT OLD.outcome_json OR
  NEW.finalized_at IS NOT OLD.finalized_at
)
BEGIN SELECT RAISE(ABORT,'WORK_EFFECT_OUTCOME_IMMUTABLE'); END;
CREATE TRIGGER work_effect_resolutions_insert_guard
BEFORE INSERT ON work_effect_resolutions
WHEN NOT EXISTS (
  SELECT 1 FROM work_prepared_effects AS e
  WHERE e.idempotency_key=NEW.effect_idempotency_key
    AND e.work_id=NEW.work_id AND e.effect_kind='attempt_dispatch'
    AND e.subject_id=NEW.attempt_id AND e.instruction_digest=NEW.instruction_digest
)
BEGIN SELECT RAISE(ABORT,'WORK_EFFECT_RESOLUTION_MISMATCH'); END;
CREATE TRIGGER work_effect_resolutions_no_delete
BEFORE DELETE ON work_effect_resolutions
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_EFFECT_RESOLUTION_IMMUTABLE'); END;
CREATE TRIGGER work_effect_resolutions_no_update
BEFORE UPDATE ON work_effect_resolutions
BEGIN SELECT RAISE(ABORT,'WORK_EFFECT_RESOLUTION_IMMUTABLE'); END;
CREATE TRIGGER work_effect_state_guard
BEFORE UPDATE OF state ON work_prepared_effects
WHEN NOT (
  OLD.state=NEW.state
  OR (OLD.state='prepared' AND NEW.state IN ('effect_started','accepted','failed','unknown'))
  OR (OLD.state='effect_started' AND NEW.state IN ('accepted','failed','unknown'))
  OR (OLD.state='unknown' AND NEW.state IN ('accepted','failed') AND EXISTS (
    SELECT 1 FROM work_effect_resolutions AS r
    WHERE r.effect_idempotency_key=OLD.idempotency_key
      AND ((r.outcome='proven_applied' AND NEW.state='accepted')
        OR (r.outcome IN ('no_effect','failed') AND NEW.state='failed'))
  ))
  OR (OLD.state='unknown' AND NEW.state IN ('accepted','failed') AND EXISTS (
    SELECT 1 FROM work_nested_effect_settlements AS n
    WHERE n.effect_idempotency_key=OLD.idempotency_key AND n.outcome=NEW.state
  ))
)
BEGIN SELECT RAISE(ABORT,'WORK_EFFECT_STATE_TRANSITION'); END;
CREATE TRIGGER work_event_capacity_guard
BEFORE INSERT ON work_events
WHEN (SELECT COUNT(*) FROM work_events WHERE work_id=NEW.work_id)
   + (SELECT COALESCE(SUM(CASE state WHEN 'prepared' THEN 2 WHEN 'effect_started' THEN 1 ELSE 0 END),0)
      FROM work_prepared_effects WHERE work_id=NEW.work_id)
   + 1 > 65536
BEGIN SELECT RAISE(ABORT,'WORK_HISTORY_EVENT_LIMIT'); END;
CREATE TRIGGER work_event_chain_guard
BEFORE INSERT ON work_events
WHEN NEW.sequence != COALESCE((SELECT MAX(sequence)+1 FROM work_events WHERE work_id=NEW.work_id),1)
  OR NEW.previous_hash IS NOT (SELECT event_hash FROM work_events WHERE work_id=NEW.work_id ORDER BY sequence DESC LIMIT 1)
BEGIN SELECT RAISE(ABORT,'WORK_EVENT_CHAIN_INVALID'); END;
CREATE TRIGGER work_events_no_delete
BEFORE DELETE ON work_events
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_EVENT_APPEND_ONLY'); END;
CREATE TRIGGER work_events_no_update
BEFORE UPDATE ON work_events BEGIN SELECT RAISE(ABORT,'WORK_EVENT_APPEND_ONLY'); END;
CREATE TRIGGER work_intents_no_delete
BEFORE DELETE ON work_idempotency_intents
WHEN OLD.work_id IS NULL OR NOT EXISTS (
  SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id
)
BEGIN SELECT RAISE(ABORT,'WORK_INTENT_IMMUTABLE'); END;
CREATE TRIGGER work_intents_no_update
BEFORE UPDATE ON work_idempotency_intents BEGIN SELECT RAISE(ABORT,'WORK_INTENT_IMMUTABLE'); END;
CREATE TRIGGER work_member_limit_guard
BEFORE INSERT ON work_members
WHEN (SELECT COUNT(*) FROM work_members WHERE work_id=NEW.work_id) >= 256
BEGIN SELECT RAISE(ABORT,'WORK_MEMBER_LIMIT'); END;
CREATE TRIGGER work_members_no_delete
BEFORE DELETE ON work_members
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_MEMBER_IMMUTABLE'); END;
CREATE TRIGGER work_members_no_update
BEFORE UPDATE ON work_members BEGIN SELECT RAISE(ABORT,'WORK_MEMBER_IMMUTABLE'); END;
CREATE TRIGGER work_nested_effect_settlements_insert_guard
BEFORE INSERT ON work_nested_effect_settlements
WHEN NOT EXISTS (
  SELECT 1 FROM work_prepared_effects AS e
  WHERE e.idempotency_key=NEW.effect_idempotency_key
    AND json_extract(e.instruction_json,'$.nestedMutationKey')=NEW.nested_mutation_key
)
BEGIN SELECT RAISE(ABORT,'WORK_NESTED_EFFECT_SETTLEMENT_MISMATCH'); END;
CREATE TRIGGER work_nested_effect_settlements_no_delete
BEFORE DELETE ON work_nested_effect_settlements
WHEN NOT EXISTS (
  SELECT 1 FROM work_prepared_effects AS e
  JOIN work_purge_authority AS p ON p.work_id=e.work_id
  WHERE e.idempotency_key=OLD.effect_idempotency_key
)
BEGIN SELECT RAISE(ABORT,'WORK_NESTED_EFFECT_SETTLEMENT_IMMUTABLE'); END;
CREATE TRIGGER work_nested_effect_settlements_no_update
BEFORE UPDATE ON work_nested_effect_settlements
BEGIN SELECT RAISE(ABORT,'WORK_NESTED_EFFECT_SETTLEMENT_IMMUTABLE'); END;
CREATE TRIGGER work_profile_attempt_authority_guard
BEFORE UPDATE OF state,process_generation ON profiles
WHEN EXISTS (
  SELECT 1 FROM work_attempts AS a
  WHERE a.account_id=OLD.id
    AND a.state IN ('claimed','dispatching','running')
    AND (NEW.state!='signed_in' OR NEW.process_generation!=a.account_generation)
)
BEGIN SELECT RAISE(ABORT,'WORK_PROFILE_ATTEMPT_AUTHORITY'); END;
CREATE TRIGGER work_receipt_chain_guard
BEFORE INSERT ON work_signal_receipts
WHEN NEW.sequence != COALESCE((
  SELECT MAX(sequence)+1 FROM work_signal_receipts WHERE signal_id=NEW.signal_id
),1)
BEGIN SELECT RAISE(ABORT,'WORK_SIGNAL_RECEIPT_SEQUENCE'); END;
CREATE TRIGGER work_receipts_no_delete
BEFORE DELETE ON work_signal_receipts
WHEN NOT EXISTS (
  SELECT 1 FROM work_signals AS s
  JOIN work_purge_authority AS p ON p.work_id=s.work_id
  WHERE s.id=OLD.signal_id
)
BEGIN SELECT RAISE(ABORT,'WORK_SIGNAL_RECEIPT_IMMUTABLE'); END;
CREATE TRIGGER work_receipts_no_update
BEFORE UPDATE ON work_signal_receipts BEGIN SELECT RAISE(ABORT,'WORK_SIGNAL_RECEIPT_IMMUTABLE'); END;
CREATE TRIGGER work_release_tombstones_no_update
BEFORE UPDATE ON work_release_tombstones
BEGIN SELECT RAISE(ABORT,'WORK_RELEASE_TOMBSTONE_IMMUTABLE'); END;
CREATE TRIGGER work_retained_limit_guard
BEFORE INSERT ON works
WHEN (SELECT COUNT(*) FROM works) >= 8192
BEGIN SELECT RAISE(ABORT,'WORK_RETAINED_LIMIT'); END;
CREATE TRIGGER work_review_member_guard
BEFORE INSERT ON work_reviews
WHEN NOT EXISTS (SELECT 1 FROM work_members WHERE work_id=NEW.work_id AND session_id=NEW.reviewer_session_id)
  OR EXISTS (
    SELECT 1 FROM work_submissions AS s
    WHERE s.id=NEW.submission_id AND s.worker_session_id=NEW.reviewer_session_id
  )
BEGIN SELECT RAISE(ABORT,'WORK_REVIEWER_INVALID'); END;
CREATE TRIGGER work_reviews_no_delete
BEFORE DELETE ON work_reviews
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_REVIEW_IMMUTABLE'); END;
CREATE TRIGGER work_reviews_no_update
BEFORE UPDATE ON work_reviews BEGIN SELECT RAISE(ABORT,'WORK_REVIEW_IMMUTABLE'); END;
CREATE TRIGGER work_route_authority_guard
BEFORE INSERT ON work_routes
WHEN NOT EXISTS (SELECT 1 FROM profiles WHERE id=NEW.account_id AND state!='removed')
  OR NOT EXISTS (SELECT 1 FROM projects WHERE id=NEW.project_id)
BEGIN SELECT RAISE(ABORT,'WORK_ROUTE_MISMATCH'); END;
CREATE TRIGGER work_route_limit_guard
BEFORE INSERT ON work_routes
WHEN (SELECT COUNT(*) FROM work_routes WHERE work_id=NEW.work_id) >= 64
BEGIN SELECT RAISE(ABORT,'WORK_ROUTE_LIMIT'); END;
CREATE TRIGGER work_routes_no_delete
BEFORE DELETE ON work_routes
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_ROUTE_IMMUTABLE'); END;
CREATE TRIGGER work_routes_no_update
BEFORE UPDATE ON work_routes BEGIN SELECT RAISE(ABORT,'WORK_ROUTE_IMMUTABLE'); END;
CREATE TRIGGER work_session_attempt_authority_guard
BEFORE UPDATE OF profile_id,project_id,preset,fast_enabled ON sessions
WHEN EXISTS (
  SELECT 1 FROM work_attempts AS a
  WHERE a.worker_session_id=OLD.id
    AND a.state IN ('claimed','dispatching','running','recovery_required')
    AND (
      NEW.profile_id!=a.account_id OR NEW.project_id!=a.project_id
      OR NEW.preset!=a.preset OR NEW.fast_enabled!=a.fast
    )
)
BEGIN SELECT RAISE(ABORT,'WORK_SESSION_ATTEMPT_AUTHORITY'); END;
CREATE TRIGGER work_signal_ack_guard
BEFORE INSERT ON work_signal_receipts
WHEN NEW.kind='ack' AND NOT EXISTS (
  SELECT 1 FROM work_signals AS s
  WHERE s.id=NEW.signal_id AND s.to_session_id=NEW.actor_session_id
)
BEGIN SELECT RAISE(ABORT,'WORK_SIGNAL_ACK_ACTOR_INVALID'); END;
CREATE TRIGGER work_signal_member_guard
BEFORE INSERT ON work_signals
WHEN NOT EXISTS (SELECT 1 FROM work_members WHERE work_id=NEW.work_id AND session_id=NEW.from_session_id)
  OR NOT EXISTS (SELECT 1 FROM work_members WHERE work_id=NEW.work_id AND session_id=NEW.to_session_id)
  OR NOT EXISTS (
    SELECT 1 FROM sessions AS s JOIN profiles AS p ON p.id=s.profile_id
    WHERE s.id=NEW.to_session_id AND s.state IN ('active','idle')
      AND p.state='signed_in' AND p.process_generation=NEW.target_account_generation
  )
BEGIN SELECT RAISE(ABORT,'WORK_SIGNAL_MEMBER_INVALID'); END;
CREATE TRIGGER work_signals_no_delete
BEFORE DELETE ON work_signals
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_SIGNAL_IMMUTABLE'); END;
CREATE TRIGGER work_signals_no_update
BEFORE UPDATE ON work_signals BEGIN SELECT RAISE(ABORT,'WORK_SIGNAL_IMMUTABLE'); END;
