BEFORE DELETE ON work_submissions
WHEN NOT EXISTS (SELECT 1 FROM work_purge_authority WHERE work_id=OLD.work_id)
BEGIN SELECT RAISE(ABORT,'WORK_SUBMISSION_IMMUTABLE'); END;
